214	    /**
215	     * Applies address normalization to whichever address form the request supplied, preferring the
216	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
217	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
218	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
219	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
220	     * appended - so everything downstream that reads {@code address} sees the structured value. When
221	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
222	     * earlier minimal owners backward-compatible.
223	     *
224	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
225	     */
226	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
227	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
228	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
229	            ownerFieldsDto.setAddressLine1(line1);
230	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
231	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
232	                ownerFieldsDto.setAddressLine2(line2);
233	                ownerFieldsDto.setAddress(line1 + " " + line2);
234	            } else {
235	                ownerFieldsDto.setAddressLine2(null);
236	                ownerFieldsDto.setAddress(line1);
237	            }
238	        } else {
239	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
240	        }
241	    }
