358	    /**
359	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
360	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
361	     * be a syntactically valid address; the accepted value is returned lower-cased.
362	     *
363	     * @param email the raw email value from the request, may be {@code null}
364	     * @return the lower-cased email, or {@code null} when none was supplied
365	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
366	     */
367	    private String normalizeEmail(String email) {
368	        if (email == null || email.isBlank()) {
369	            return null;
370	        }
371	        String trimmed = email.trim();
372	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
373	            throw new InvalidFieldsException(List.of("email"));
374	        }
375	        String normalized = trimmed.toLowerCase(Locale.ROOT);
376	        String domain = normalized.substring(normalized.indexOf('@') + 1);
377	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
378	            throw new InvalidFieldsException(List.of("email"));
379	        }
380	        return normalized;
381	    }
