558	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
559	    @Override
560	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
561	        applyAddressFields(ownerFieldsDto);
562	        validateRequiredFields(ownerFieldsDto);
563	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
564	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
565	        requireCityHasCapacity(ownerFieldsDto.getCity());
566	        String email = normalizeEmail(ownerFieldsDto.getEmail());
567	        HttpHeaders headers = new HttpHeaders();
568	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
569	        owner.setTelephone(telephone);
570	        owner.setEmail(email);
571	        requireUniqueIdentity(owner);
572	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
573	        if (!sharesHousehold) {
574	            requireNoHouseholdDuplicate(owner);
575	        }
576	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
577	        LocalDate effectiveDate = owner.getRegistrationDate() != null
578	            ? owner.getRegistrationDate() : LocalDate.now();
579	        LocalDate registrationDate = toBusinessDay(effectiveDate);
580	        owner.setRegistrationDate(registrationDate);
581	        requireDailyLimitNotReached(registrationDate);
582	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
583	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
584	        owner.setPossibleDuplicate(possibleDuplicate != null);
585	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
586	        this.clinicService.saveOwner(owner);
587	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
588	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
589	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
590	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
591	        headers.setLocation(UriComponentsBuilder.newInstance()
592	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
593	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
594	    }
