649	            Pet currentPet = this.clinicService.findPetById(petId);
650	            if (currentPet != null) {
651	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
652	                currentPet.setName(petFieldsDto.getName());
653	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
654	                this.clinicService.savePet(currentPet);
655	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
656	            }
657	        }
658	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
659	    }
660	
661	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
662	    @Override
663	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
664	        HttpHeaders headers = new HttpHeaders();
665	        Visit visit = visitMapper.toVisit(visitFieldsDto);
666	        Pet pet = new Pet();
667	        pet.setId(petId);
668	        visit.setPet(pet);
669	        this.clinicService.saveVisit(visit);
670	        VisitDto visitDto = visitMapper.toVisitDto(visit);
671	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
672	            .buildAndExpand(visit.getId()).toUri());
673	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
674	    }
675	
676	
677	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
678	    @Override
679	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
680	        Owner owner = this.clinicService.findOwnerById(ownerId);
681	        if (owner != null) {
682	            Pet pet = owner.getPet(petId);
683	            if (pet != null) {
684	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
685	            }
686	        }
687	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
688	    }
689	}
